package mz.bam.seeky.android;
import android.content.*;import android.database.Cursor;import android.net.Uri;import java.util.*;
/** Stores the last successfully displayed document; the reader's own per-URI positions remain authoritative. */
final class LastReading {
 static final String PREFS="seeky_last_reading";
 static final class Saved {final String uri,name,mime,title,path;final long material;final boolean fullScreen;Saved(SharedPreferences p){uri=p.getString("uri","");name=p.getString("name","");mime=p.getString("mime","");title=p.getString("title",name);path=p.getString("path","");material=p.getLong("material",0);fullScreen=p.getBoolean("full_screen",true);}boolean exists(){return !uri.isEmpty();}Intent intent(Context c){return new Intent(c,ReaderActivity.class).setDataAndType(Uri.parse(uri),mime).putExtra("name",name).putExtra("study_title",title).putExtra("study_path",path).putExtra("study_material",material).putExtra("full_screen",fullScreen);}}
 static Saved get(Context c){return new Saved(c.getSharedPreferences(PREFS,0));}
 static void remember(Context c,Uri uri,String name,String mime,String title,String path,long material){remember(c,uri,name,mime,title,path,material,true);}
 static void remember(Context c,Uri uri,String name,String mime,String title,String path,long material,boolean fullScreen){if(uri==null||!Arrays.asList("content","file").contains(uri.getScheme())||!BookQuery.accepts(name,mime))return;c.getSharedPreferences(PREFS,0).edit().putString("uri",uri.toString()).putString("name",name).putString("mime",mime).putString("title",title==null||title.isEmpty()?name:title).putString("path",path==null?"":path).putLong("material",material).putBoolean("full_screen",fullScreen).putBoolean("legacy_checked",true).apply();}
 static void forget(Context c,long material){Saved saved=get(c);if(saved.material==material||saved.uri.equals(StudyFileProvider.uri(c,material).toString()))c.getSharedPreferences(PREFS,0).edit().remove("uri").remove("material").apply();}
 static void migrate(Context c,StudyStore store){SharedPreferences last=c.getSharedPreferences(PREFS,0);if(last.contains("uri")||last.getBoolean("legacy_checked",false))return;SharedPreferences positions=c.getSharedPreferences("seeky",0);try(Cursor rows=store.getReadableDatabase().query("materials",new String[]{"id","name","mime","title"},BookQuery.RAW_FORMATS,null,null,null,"updated DESC,id DESC")){while(rows.moveToNext()){long id=rows.getLong(0);Uri uri=StudyFileProvider.uri(c,id);if(positions.contains("reader_page_"+uri)||positions.contains("reader_chapter_"+uri)||positions.contains("reader_scroll_"+uri+":0")){remember(c,uri,rows.getString(1),rows.getString(2),rows.getString(3),AppLanguage.text(c,"Livros"),id);break;}}}last.edit().putBoolean("legacy_checked",true).apply();}
 private LastReading(){}
}
